#!/usr/bin/env node
import path from 'node:path';

import { Option, program } from '@commander-js/extra-typings';
import {
  consoleReporter,
  getWarningCount,
  isString,
  LOG_LEVELS,
  OutputClient,
  OutputMode,
  resetWarnings,
  resolveLogLevel,
  setLogLevel,
  setProjectName,
  startMessage,
  SupportedFormatter,
  withReporter,
} from '@orval/core';

import pkg from '../../package.json';
import { generateSpec } from '../generate-spec';
import { logger } from '../logger';
import {
  findConfigFile,
  getConfigProjects,
  loadConfigFile,
} from '../utils/config';
import { normalizeOptions } from '../utils/options';
import { startWatcher } from '../utils/watcher';
const orvalMessage = startMessage({
  name: pkg.name,
  version: pkg.version,
  description: pkg.description,
});
const cli = program
  .name('orval')
  .description(
    'Instantly generate TypeScript clients from your OpenAPI specification',
  )
  .version(pkg.version);

cli
  .addOption(
    new Option('-o, --output <path>', 'output file destination').conflicts([
      'config',
      'project',
    ]),
  )
  .addOption(
    new Option(
      '-i, --input <path>',
      'input file (yaml or json openapi specs)',
    ).conflicts(['config', 'project']),
  )
  .addOption(
    new Option(
      '-c, --config <path>',
      'override flags by a config file',
    ).conflicts(['input', 'output']),
  )
  .addOption(
    new Option(
      '-p, --project <name...>',
      'focus one or more projects of the config',
    ).conflicts(['input', 'output']),
  )
  .addOption(
    new Option('-m, --mode <name>', 'default mode that will be used').choices(
      Object.values(OutputMode),
    ),
  )
  .option(
    '-w, --watch [paths...]',
    'Watch mode, if path is not specified, it watches the input target',
  )
  .addOption(
    new Option('--client <name>', 'default client that will be used').choices(
      Object.values(OutputClient),
    ),
  )
  .option('--mock', 'activate mock generation (msw handlers + faker factories)')
  .option('--clean [paths...]', 'Clean output directory')
  .addOption(
    new Option(
      '--formatter <name>',
      'Format generated files (prettier, biome, oxfmt)',
    ).choices(Object.values(SupportedFormatter)),
  )
  .option('--tsconfig <path>', 'path to your tsconfig file')
  .addOption(
    new Option('--verbose', 'Set the log level to verbose').conflicts([
      'quiet',
      'logLevel',
    ]),
  )
  .addOption(
    new Option('--quiet', 'Set the log level to warn').conflicts([
      'verbose',
      'logLevel',
    ]),
  )
  .addOption(
    new Option('--log-level <level>', 'Set the log level')
      .choices(LOG_LEVELS)
      .conflicts(['verbose', 'quiet']),
  )
  .option(
    '--fail-on-warnings',
    'Exit with error code 1 when warnings are emitted',
  )
  .action(async (options) => {
    await withReporter(consoleReporter, async () => {
      resetWarnings();

      if (isString(options.input) && isString(options.output)) {
        setLogLevel(
          resolveLogLevel({
            verbose: options.verbose,
            quiet: options.quiet,
            logLevel: options.logLevel,
          }),
        );
        logger.info(orvalMessage);

        const normalizedOptions = await normalizeOptions({
          input: options.input,
          output: {
            target: options.output,
            clean: options.clean,
            formatter: options.formatter,
            mock: options.mock,
            client: options.client,
            mode: options.mode,
            tsconfig: options.tsconfig,
          },
        });

        try {
          await generateSpec(process.cwd(), normalizedOptions);
        } catch (error) {
          logger.error(error);
          process.exit(1);
        }

        if (options.watch) {
          await startWatcher(
            options.watch,
            async () => {
              resetWarnings();
              try {
                await generateSpec(process.cwd(), normalizedOptions);
              } catch (error) {
                logger.error(error);
                process.exit(1);
              }
              if (options.failOnWarnings && getWarningCount() > 0) {
                logger.error(
                  `Process exited with ${getWarningCount()} warning(s) due to --fail-on-warnings flag`,
                );
                process.exit(1);
              }
            },
            normalizedOptions.input.target as string,
          );
        }
      } else {
        const configFilePath = findConfigFile(options.config);
        const workspace = path.dirname(configFilePath);
        const configFile = await loadConfigFile(configFilePath);
        const projects = Object.fromEntries(getConfigProjects(configFile));

        setLogLevel(
          resolveLogLevel({
            verbose: options.verbose,
            quiet: options.quiet,
            logLevel: options.logLevel ?? configFile.logLevel,
          }),
        );
        logger.info(orvalMessage);

        const missingProjects = options.project?.filter(
          (p) => !Object.hasOwn(projects, p),
        );

        if (missingProjects?.length) {
          logger.error(
            `Project not found in config: ${missingProjects.join(', ')}`,
          );
          process.exit(1);
        }

        const configs = Object.entries(projects).filter(
          ([projectName]) =>
            // only filter by project if specified
            !Array.isArray(options.project) ||
            options.project.includes(projectName),
        );

        let hasErrors = false;
        for (const [projectName, config] of configs) {
          setProjectName(projectName);
          const normalizedOptions = await normalizeOptions(
            config,
            workspace,
            options,
          );

          try {
            await generateSpec(workspace, normalizedOptions, projectName);
          } catch (error) {
            hasErrors = true;
            logger.error(error);
          }

          if (options.watch !== undefined) {
            const fileToWatch = isString(normalizedOptions.input.target)
              ? normalizedOptions.input.target
              : undefined;

            await startWatcher(
              options.watch,
              async () => {
                resetWarnings();
                try {
                  await generateSpec(workspace, normalizedOptions, projectName);
                } catch (error) {
                  logger.error(error);
                }
                if (options.failOnWarnings && getWarningCount() > 0) {
                  logger.error(
                    `Process exited with ${getWarningCount()} warning(s) due to --fail-on-warnings flag`,
                  );
                  process.exit(1);
                }
              },
              fileToWatch,
            );
          }
        }

        setProjectName(); // clears project name

        if (hasErrors) {
          logger.error('One or more project failed, see above for details');
          process.exit(1);
        }
      }

      if (options.failOnWarnings && getWarningCount() > 0) {
        logger.error(
          `Process exited with ${getWarningCount()} warning(s) due to --fail-on-warnings flag`,
        );
        process.exit(1);
      }
    });
  });

await cli.parseAsync(process.argv);
